import{_ as l,l as i,o as t,c as s,v as o,p as B,x as r,d as E,i as A,S as p,b as a}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"股指期货保证金与贴水","description":"","frontmatter":{"title":"股指期货保证金与贴水","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-index-fut-basis.md","filePath":"quant/cn-index-fut-basis.md","lastUpdated":1789023840000}'),d={name:"quant/cn-index-fut-basis.md"};function h(u,e,F,c,m,C){const n=i("Mermaid");return t(),s("div",null,[e[1]||(e[1]=o('<h1 id="股指期货保证金与贴水" tabindex="-1">股指期货保证金与贴水 <a class="header-anchor" href="#股指期货保证金与贴水" aria-label="Permalink to &quot;股指期货保证金与贴水&quot;">​</a></h1><div class="epigraph"><p>股指期货实行当日无负债结算。交易所规定最低交易保证金比例与涨跌停板，会员可在此之上加收。合约到期现金交割，交割结算价为最后交易日标的指数最后两小时的算术平均价。</p><footer>—— 中国金融期货交易所股指期货合约及结算细则；沪深 300、上证 50、中证 500、中证 1000 股指期货合约表</footer></div><p><a href="/quant/cb-call-put">上一课</a>把转债打新写成扣中签率与首日价格带的期望，强赎通知期内以强制转股为主，回售与下修互为对手。缺口是股票组合的空头工具主要在期货：股指期货保证金按合约价值占用并每日盯市，贴水含分红折现与对冲拥挤，不是免费的指数低估。到期现金交割对准最后两小时指数算术平均。本课写 IF/IH/IC/IM 的保证金、结算与升贴水，不重写转债条款日历。一般期现关系见 <a href="/quant/index-arb">指数套利</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>持有成本给出远期公允值 \\(F = S e^{(r-q)\\tau}\\)，\\(q\\) 为预期红利率。A 股分红集中在二季度，IF、IH 在除权季节出现季节性贴水是分红的折现，不是错误定价。IC、IM 长期深度贴水，则更多来自中性与量化对冲的持续卖压：现货多头需要空头工具，融券标的与券源受限，期货成为主要出口。贴水年化</p> \\[b_t = \\left(\\frac{F_{t,T}}{S_t}-1\\right)\\frac{365}{T-t} \\]<p>在远月可以到很高的数字，但把 \\(b_t\\) 当成持有到期的确定收益，忽略了：保证金追加、升贴水继续变深、到期必须展期、以及现货一揽子不可精确复制。贴水变深时空头盈利、多头亏损，这是盯市，不是分红的实现。</p><p>保证金把杠杆变成路径依赖。交易所最低保证金在合约表上可低至合约价值的 8%，会员与套保、投机账户常见加收到 10%–15% 一带，并随市场压力上调。2015 年之后一度大幅提高保证金与平今手续费，其后逐步恢复；具体比例以中金所与期货公司当时公告为准。资金占用是 \\(\\mathrm{margin}=m\\times F\\times \\text{乘数}\\times\\text{手数}\\)，结算价变动直接划转现金。现货涨跌停时期货仍按自身 ±10% 停板交易，基差可以瞬间扩大到无法用篮子对锁的宽度。</p><h3 id="结算价、交割结算价与最后两小时" tabindex="-1">结算价、交割结算价与最后两小时 <a class="header-anchor" href="#结算价、交割结算价与最后两小时" aria-label="Permalink to &quot;结算价、交割结算价与最后两小时&quot;">​</a></h3><p>每日结算价一般取最后一小时成交量加权均价（规则文本为准），用于当日盈亏与下一交易日涨跌停基准。到期日现金交割不用期货最后成交价，而用标的指数最后两小时算术平均价。于是到期日的「收敛」是期货向这段现货均价收敛，不是向 15:00 的指数点收敛。操纵或冲击若集中在最后两小时之外，对交割结算价影响有限；反之，最后两小时的现货流动性决定交割质量。开仓用收盘指数算基差、平仓按交割结算价，会留下一段定义差。</p><p><span class="marginnote">合约月份为当月、下月及随后两个季月。远月贴水年化通常高于近月，一部分是期限溢价与分红不确定性，一部分是远月流动性差、冲击大。用远月年化贴水外推近月可实现展期收益，会把不可成交的曲线当成收益。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>可交易基差必须用可复制现货，而不是指数点位。现货腿可以是成分一揽子、抽样篮子或对应 ETF。计算持有成本时，\\(r\\) 用融资或回购利率而非国债无风险利率，\\(q\\) 用预测分红而非事后实现——事后 \\(q\\) 制造前视。把期货有效价差、篮子冲击、ETF 折溢价、手续费（含平今，若当时对平今加收）与保证金占用成本加进无套利带。仅当 \\(|F-S_{\\mathrm{basket}}e^{(r-q)\\tau}|\\) 超出半宽，且篮子可同时成交时，才允许期现对锁。</p><p>对冲盘卖期货、持有现货的结构，赚的是贴水收敛或分红，赔的是贴水变深与保证金追加。仓位应写成「在保证金 \\(m\\) 与最大回撤下仍能扛住贴水再扩大 \\(x\\) 个点」的手数，而不是按名义本金满打。套保额度、持仓限额与异常交易监管会在压力期收紧可开空数量，使贴水暂时没有足够的多头去收。这不是模型失灵，是制度供给。</p><h3 id="展期、平今与升贴水曲线" tabindex="-1">展期、平今与升贴水曲线 <a class="header-anchor" href="#展期、平今与升贴水曲线" aria-label="Permalink to &quot;展期、平今与升贴水曲线&quot;">​</a></h3><p>近月到期须展期到次月或季月。展期成交把近月贴水换成远月贴水，实现的是两条合约之间的价差，不是指数收益。若曲线远月更贴，空头展期要付出；若近月贴水更深，空头展期获利。平今手续费在历史上曾远高于开仓，用以抑制日内频繁开平；费率随政策调整，回测必须用当时费率而不是当前一览表。升贴水曲线应分 IF/IH 与 IC/IM 两张图：前者更接近分红与利率，后者更接近对冲拥挤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>保证金的中央对手方是中金所，每日按结算价划转，不足追加，方向对称。这与<a href="/quant/cn-margin-trading">融资融券保证金与强平</a>不同：两融的担保品是证券市值，股票跌停可能卖不出；期货在停板内仍结算，停板外无法成交但已发生的盈亏在可成交一侧仍划转。期货多头在现货连续跌停、期货贴水加深时，会同时承受现货无法卖出（若有现货腿）与期货追加保证金。单边持有期货则只面对现金追加。</p><p>贴水的供给来自需要卖指数的机构，需求来自愿意提供空头的套利与多头配置。融券难、做空工具少时，供给压过需求，贴水可以长期存在。分红落地后 IF/IH 贴水应收敛一部分；若未收敛，剩余才是风险溢价或拥挤。用贴水年化直接加进股票多头的「增强」，等于把一个需要保证金与展期的空头头寸，写成了现货的确定性 alpha。</p><p><span class="marginnote">交割结算价是指数两小时算术平均，不是期货 VWAP。到期日若只在期货上把基差「砸平」而不在现货上对锁，面对的是平均价风险，不是零。</span></p><h3 id="涨跌停与缺腿" tabindex="-1">涨跌停与缺腿 <a class="header-anchor" href="#涨跌停与缺腿" aria-label="Permalink to &quot;涨跌停与缺腿&quot;">​</a></h3><p>现货涨跌停使一揽子缺腿，期货 ±10% 的停板与指数点位的停板并不逐只对应：指数可以因为部分成分停牌或跌停而缓慢移动，期货可以先到板。此时基差扩大，按旧带加仓是在交易流动性枯竭。套保账户若因保证金不足被强平，会在最差的基差上变成单边。风控应把「现货可复制比例」写成状态：低于阈值则禁止加开期现仓，只允许减仓。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用指数点位代替可买篮子。不要把交易所最低保证金当成期货公司实际比例。不要忽略平今与交割手续费的历史断点。不要把 IC/IM 的长期贴水写成可无限扩容的保险费——持仓限额与额度会封顶。股指期权的保证金与希腊另有规则，不能与期货混用一张比例表。</p><p>容量受最差成分深度、ETF 申赎与期货盘口同时约束。报告应分开：分红季节的 IF/IH 贴水、非分红季节的残余、IC/IM 对冲拥挤指标，以及保证金压力测试（贴水再扩大、双向开板）下的追加路径。</p><p><span class="marginnote">合约表上的「最低交易保证金 8%」是交易所下限。会员加收之后，同样的贴水年化对应的资金收益率会成倍下降。用下限去宣传「贴水增强」，把杠杆算大了。</span></p>',26)),(t(),B(p,null,{default:r(()=>[A(n,{id:"mermaid-74",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%8F%AF%E5%A4%8D%E5%88%B6%E7%AF%AE%E5%AD%90%20%2F%20ETF%22%5D%20--%3E%20COC%5B%22%E6%8C%81%E6%9C%89%E6%88%90%E6%9C%AC%20r%E2%88%92q%22%5D%0A%20%20COC%20--%3E%20FSTAR%5B%22%E5%85%AC%E5%85%81%E8%BF%9C%E6%9C%9F%22%5D%0A%20%20F%5B%22%E6%9C%9F%E8%B4%A7%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20BAS%5B%22%E5%8D%87%E8%B4%B4%E6%B0%B4%22%5D%0A%20%20FSTAR%20--%3E%20BAS%0A%20%20M%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E6%AF%94%E4%BE%8B%20%C3%97%20%E4%BC%9A%E5%91%98%E5%8A%A0%E6%94%B6%22%5D%20--%3E%20FUT%5B%22%E7%9B%AF%E5%B8%82%E4%B8%8E%E8%BF%BD%E5%8A%A0%22%5D%0A%20%20F%20--%3E%20FUT%0A%20%20BAS%20--%3E%7C%22%E5%B8%A6%E5%A4%96%E4%B8%94%E7%AF%AE%E5%AD%90%E5%8F%AF%E6%88%90%E4%BA%A4%22%7C%20ARB%5B%22%E6%9C%9F%E7%8E%B0%E5%AF%B9%E9%94%81%22%5D%0A%20%20DIV%5B%22%E5%88%86%E7%BA%A2%E5%AD%A3%E8%8A%82%22%5D%20--%3E%20BAS%0A%20%20HEDGE%5B%22%E5%AF%B9%E5%86%B2%E5%8D%96%E5%8E%8B%20IC%2FIM%22%5D%20--%3E%20BAS%0A%20%20LIMIT%5B%22%E7%8E%B0%E8%B4%A7%E6%B6%A8%E8%B7%8C%E5%81%9C%E7%BC%BA%E8%85%BF%22%5D%20--%3E%7C%22%E5%B8%A6%E5%8F%98%E5%AE%BD%22%7C%20OPEN%5B%22%E8%B4%B4%E6%B0%B4%E5%8F%AF%E6%9B%B4%E6%B7%B1%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[E("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"股指期货保证金按合约价值比例占用并每日盯市，实际比例以会员加收为准，不是合约表下限。"),a("li",null,"贴水含分红折现与对冲拥挤；IC/IM 的深度贴水主要是空头工具稀缺，不是免费的指数低估。"),a("li",null,"到期现金交割对准最后两小时指数算术平均，基差定义必须与结算定义一致。"),a("li",null,"无套利带由篮子冲击、涨跌停、手续费与保证金占用共同决定；缺腿时带会突然变宽。"),a("li",null,"展期实现的是跨月价差，平今费率有历史断点，须按当时规则回测。"),a("li",null,"出处：中国金融期货交易所 IF/IH/IC/IM 合约表、交易规则与结算细则；保证金与手续费调整以交易所公告为准。")],-1))])}const q=l(d,[["render",h]]);export{f as __pageData,q as default};
